// Verify the HMAC signature Convex put on the request. Signed string:
// `${timestamp}.POST.${path}.${body}` (same format as convex/hmac.ts).
const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const { headers, body } = $input.first().json;
const ts = headers['x-timestamp'] || '';
const sig = headers['x-signature'] || '';
const expected = crypto.createHmac('sha256', secret)
  .update(`${ts}.POST./webhook/lendloop-request.${JSON.stringify(body)}`).digest('hex');
const fresh = Math.abs(Date.now() - Number(ts)) < 5 * 60 * 1000;   // replay window
let valid = false;
if (secret && sig && fresh && sig.length === expected.length) {
  valid = crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
}
return [{ json: { valid, payload: valid ? body : null } }];

// Uses ONLY the fields it needs. A logged mock notification is the delivery channel.
const p = $input.first().json.payload;
const text = {
  request_created: `New borrow request for your "${p.toolName}" (${p.startDate} to ${p.endDate}).`,
  request_approved: `Your request for "${p.toolName}" was approved (${p.startDate} to ${p.endDate}).`,
  request_declined: `Your request for "${p.toolName}" was declined.`,
  loan_returned: `"${p.toolName}" has been marked as returned. Thank you!`,
}[p.event] || `Update on "${p.toolName}": ${p.status}`;
console.log(`[MOCK NOTIFICATION] to=${p.recipientName} <${p.recipientEmail}> :: ${text}`);
return [{ json: { to: p.recipientEmail, message: text, loanId: p.loanId, event: p.event } }];
